    if (!param.pageNo || param.pageNo <= 0 || !param.pageSize || param.pageSize <= 0) {
      return this.error("\u4F20\u5165\u6B63\u786E\u9875\u7801\u6216\u6570\u91CF");
    }
    if (param.uids instanceof Array)
      param.uids = param.uids.join(",");
    return this.get("/list", param);
